from pathlib import Path
from collections import Counter
import json,hashlib,math
base=Path('/tmp/neospice-joss-checkpoint29-coolmos')
labels=['before47','after47','after42','stage2-47','stage2-42'];data={};runs={};hashes={}
def check(r):
 p=Path(r['path']);digest=hashlib.sha256(p.read_bytes()).hexdigest()
 assert p.stat().st_size==r['bytes'] and digest==r['sha256'],p
 hashes[str(p)]=digest
for label in labels:
 root=base/label;plan=json.loads((root/'run.json').read_text());assert plan['complete'] and plan['completed_fixtures']==482
 records={};counts={}
 for item in plan['fixtures']:
  key=(item['case_id'],item['variant']);p=root/'cases'/key[0]/key[1]/'comparison.json';r=json.loads(p.read_text())
  assert r['fixture_id']==item['fixture_id'];check(r['materialized_fixture'])
  for engine in ['neospice','reference']:
   assert json.loads((p.parent/(engine+'.json')).read_text())==r[engine]
   for artifact in ['stdout','stderr','raw']:
    if r[engine][artifact]:check(r[engine][artifact])
  for c in r['comparisons']:
   if c['status']=='compared':
    assert math.isfinite(c['neo']) and math.isfinite(c['ng'])
    diff=abs(c['neo']-c['ng']);tol=.001*max(abs(c['neo']),abs(c['ng']))+(1e-9 if c['var'].startswith('i(') else 1e-6)
    assert diff==c['diff'] and tol==c['tol'] and (diff<=tol)==c['ok']
  counts.setdefault(key[1],Counter())[r['status']]+=1;records[key]=r
 assert {k:dict(v) for k,v in counts.items()}==plan['counts_by_variant']
 assert len(list((root/'cases').glob('*/*/comparison.json')))==482
 data[label]=records;runs[label]=dict(counts=plan['counts_by_variant'],fixtures=482)
transitions={}
for before,after in [('before47','after47'),('after47','stage2-47'),('after42','stage2-42')]:
 a,b=data[before],data[after];assert a.keys()==b.keys();changed=[];engine_changes={e:[] for e in ['neospice','reference']}
 for key,x in a.items():
  y=b[key];assert x['materialized_fixture']['sha256']==y['materialized_fixture']['sha256'] and x['identity']==y['identity']
  if x['status']!=y['status']:changed.append(dict(case_id=key[0],variant=key[1],identity=x['identity'],before=x['status'],after=y['status']))
  for e in engine_changes:
   fields=[f for f in ['ok','returncode','failure_class','values'] if x[e][f]!=y[e][f]]
   if fields:engine_changes[e].append(dict(case_id=key[0],variant=key[1],identity=x['identity'],fields=fields))
 transitions[before+' -> '+after]=dict(changed_outcomes=changed,engine_changes=engine_changes)
assert not transitions['before47 -> after47']['engine_changes']['neospice']
r=dict(runs=runs,transitions=transitions,artifact_sha256=hashes,verified_artifact_files=len(hashes),scope='All241 CoolMOSsimp.lib declarations with both original variants; not held out. Independent scalar formula and fixture/result artifact audit.',script=Path(__file__).read_text())
p=Path('docs/evidence/joss/2026-09-11-checkpoint29-coolmos-audit.json');assert not p.exists();p.write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps(dict(path=str(p),verified_artifacts=len(hashes),transitions={k:dict(outcomes=len(v['changed_outcomes']),engine_changes={e:len(w) for e,w in v['engine_changes'].items()}) for k,v in transitions.items()}),indent=2))
